begin;
with j as (select * from jsonb_to_recordset($law7d0019$[{"code_id":"GK_RF","article_number":"106.5","version_date":"1994-11-30","article_text":"1. Член производственного кооператива по своему усмотрению вправе выйти из кооператива. В этом случае ему должна быть выплачена стоимость пая или должно быть выдано имущество, стоимость которого соответствует стоимости его пая, а также должны быть произведены другие выплаты, предусмотренные уставом кооператива.\n\nВыплата стоимости пая или выдача д\n\nругого имущества выходящему члену кооператива производится по окончании финансового года и утверждении бухгалтерской (финансовой) отчетности кооператива, если иное не предусмотрено уставом кооператива.\n\n2. Член производственного кооператива может быть исключен из кооператива по решению общего собрания в случае неисполнения или ненадлежащего исполнения обязанностей, возложенных на него уставом кооператива, а также в других случаях, предусмотренных законом и уставом кооператива.\n\nЧлен правления кооператива может быть исключен из кооператива по решению общего собрания в связи с членством в аналогичном кооперативе.\n\nЧлен кооператива, исключенный из него, имеет право на получение пая и других выплат, предусмотренных уставом кооператива, в соответствии с пунктом 1 настоящей статьи.\n\n3. Член производственного кооператива вправе передать свой пай или его часть другому члену кооператива, если иное не предусмотрено законом и уставом кооператива.\n\nПередача пая или его части гражданину, не являющемуся членом кооператива, допускается с согласия общего собрания членов кооператива. В этом случае другие члены кооператива пользуются преимущественным правом покупки такого пая или его части.\n\n4. В случае смерти члена производственного кооператива его наследники могут быть приняты в члены кооператива, если иное не предусмотрено уставом кооператива. В противном случае кооператив выплачивает наследникам стоимость пая умершего члена кооператива.\n\n5. Обращение взыскания на пай члена производственного кооператива по долгам члена кооператива допускается лишь при недостатке иного его имущества для покрытия таких долгов в порядке, установленном законом и уставом кооператива. Взыскание по долгам члена кооператива не может быть обращено на неделимые фонды кооператива.","article_title":"Статья 106.5. Прекращение членства в производственном кооперативе и переход пая","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93168bf7a28378628566e02cf64f31797b35e239edcfde5b0e2b2eb3f1267fac"},{"code_id":"GK_RF","article_number":"106.6","version_date":"1994-11-30","article_text":"Производственный кооператив по решению его членов, принятому единогласно, может преобразоваться в хозяйственное товарищество или общество.\n\n§ 3. (Статьи 107 - 112)\n\n(Параграф утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 106.6. Преобразование производственного кооператива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63b6f892e31ff26e12eda91be9d7d8fedbb48712295e13f055a704858bfa4fd0"},{"code_id":"GK_RF","article_number":"113","version_date":"1994-11-30","article_text":"1. Унитарным предприятием признается коммерческая организация, не наделенная правом собственности на закрепленное за ней собственником имущество. Имущество унитарного предприятия является неделимым и не может быть распределено по вкладам (долям, паям), в том числе между работниками предприятия.\n\nВ организационно-правовой форме унитарных предприятий действуют государственные и муниципальные предприятия.\n\nВ случаях и в порядке, которые предусмотрены законом о государственных и муниципальных унитарных предприятиях, на базе государственного или муниципального имущества может быть создано унитарное казенное предприятие (казенное предприятие).\n\n2. Имущество государственного или муниципального унитарного предприятия находится в государственной или муниципальной собственности и принадлежит такому предприятию на праве хозяйственного ведения или оперативного управления.\n\nПрава унитарного предприятия на закрепленное за ним имущество определяются в соответствии с настоящим Кодексом и законом о государственных и муниципальных унитарных предприятиях.\n\n3. Учредительным документом унитарного предприятия является его устав, утверждаемый уполномоченным государственным органом или органом местного самоуправления, если иное не предусмотрено законом.\n\nУстав унитарного предприятия должен содержать сведения о его фирменном наименовании и месте его нахождения, предмете и целях его деятельности. Устав унитарного предприятия, не являющегося казенным, должен содержать также сведения о размере уставного фонда унитарного предприятия.\n\n4. Фирменное наименование унитарного предприятия должно содержать указание на собственника его имущества. Фирменное наименование казенного предприятия, кроме того, должно содержать указание на то, что такое предприятие является казенным.\n\n5. Органом унитарного предприятия является руководитель предприятия, который назначается уполномоченным собственником органом, если иное не предусмотрено законом, и ему подотчетен.\n\n6. Унитарное предприятие отвечает по своим обязательствам всем принадлежащим ему имуществом.\n\nУнитарное предприятие не несет ответственность по обязательствам собственника его имущества.\n\nСобственник имущества унитарного предприятия, за исключением собственника имущества казенного предприятия, не отвечает по обязательствам своего унитарного предприятия. Собственник имущества казенного предприятия несет субсидиарную ответственность по обязательствам такого предприятия при недостаточности его имущества.\n\n7. Правовое положение унитарных предприятий определяется настоящим Кодексом и законом о государственных и муниципальных унитарных предприятиях.\n\n8. Унитарное предприятие может быть реорганизовано в соответствии с законом о государственных и муниципальных унитарных предприятиях и законами о приватизации.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 113. Основные положения об унитарном предприятии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64416a4b85492b5fba6d9e235f8662c015102d8f214fb39aedd5f05b71039b4b"},{"code_id":"GK_RF","article_number":"114","version_date":"1994-11-30","article_text":"1. Унитарное предприятие создается от имени публично-правового образования (статья 125) решением уполномоченного на то государственного органа или органа местного самоуправления.\n\n2. Минимальный размер уставного фонда унитарного предприятия определяется законом о государственных и муниципальных унитарных предприятиях.\n\n3. Порядок формирования уставного фонда унитарного предприятия устанавливается законом о государственных и муниципальных унитарных предприятиях.\n\n4. Если по окончании финансового года стоимость чистых активов унитарного предприятия окажется меньше размера уставного фонда, орган, уполномоченный создавать такие предприятия, обязан произвести в установленном порядке уменьшение уставного фонда. Если стоимость чистых активов становится меньше размера, определенного законом, унитарное предприятие может быть ликвидировано по решению суда.\n\n5. В случае принятия решения об уменьшении уставного фонда унитарное предприятие обязано уведомить об этом в письменной форме своих кредиторов.\n\nКредитор унитарного предприятия вправе потребовать прекращения или досрочного исполнения обязательства, должником по которому является это предприятие, и возмещения убытков.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 114. Создание унитарного предприятия и его уставный фонд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8b7bd310edd84570c2977339abe058bd63c00eac0b1a1d8a8ffdbd790edba52"},{"code_id":"GK_RF","article_number":"115","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n§ 5. (Статьи 116 - 123)\n\n(Параграф утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n(Дополнение параграфом - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n1. Общие положения о некоммерческих корпоративных организациях","article_title":"Статья 115. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0797a989744fc6ef43b83508d881d02fb0fe421cbc2fa9a613759b8c6f69e8cd"},{"code_id":"GK_RF","article_number":"12","version_date":"1994-11-30","article_text":"Защита гражданских прав осуществляется путем:\n\nпризнания права;\n\nвосстановления положения, существовавшего до нарушения права, и пресечения действий, нарушающих право или создающих угрозу его нарушения;\n\nпризнания оспоримой сделки недействительной и применения последствий ее недействительности, применения последствий недействительности ничтожной сделки;\n\nпризнания недействительным решения собрания; (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\nпризнания недействительным акта государственного органа или органа местного самоуправления;\n\nсамозащиты права;\n\nприсуждения к исполнению обязанности в натуре;\n\nвозмещения убытков;\n\nвзыскания неустойки;\n\nкомпенсации морального вреда;\n\nпрекращения или изменения правоотношения;\n\nнеприменения судом акта государственного органа или органа местного самоуправления, противоречащего закону;\n\nиными способами, предусмотренными законом.","article_title":"Статья 12. Способы защиты гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0042545226f597f1345caa2658dc7a81e0e520fa8b19c2a6a8f046f9b64f7ee9"},{"code_id":"GK_RF","article_number":"123.1","version_date":"1994-11-30","article_text":"1. Некоммерческими корпоративными организациями признаются юридические лица, которые не преследуют извлечение прибыли в качестве основной цели своей деятельности и не распределяют полученную прибыль между участниками (пункт 1 статьи 50 и статья 651), учредители (участники) которых приобретают право участия (членства) в них и формируют их высший орган в соответствии с пунктом 1 статьи 653 настоящего Кодекса.\n\n2. Потребительский кооператив","article_title":"Статья 123.1. Основные положения о некоммерческих корпоративных организациях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c627f35ba05fc0f00d53ab5f10bf9e916b14e9d304c0a0eaf47d85fb97c64556"},{"code_id":"GK_RF","article_number":"123.10","version_date":"1994-11-30","article_text":"1. К исключительной компетенции высшего органа ассоциации (союза) наряду с вопросами, указанными в пункте 2 статьи 653 настоящего Кодекса, относится также принятие решений о порядке определения размера и способа уплаты членских взносов, о дополнительных имущественных взносах членов ассоциации (союза) в ее имущество и о размере их субсидиарной ответственности по обязательствам ассоциации (союза), если такая ответственность предусмотрена законом или уставом.\n\n2. В ассоциации (союзе) образуется единоличный исполнительный орган (председатель, президент и т.п.) и могут образовываться постоянно действующие коллегиальные исполнительные органы (совет, правление, президиум и т.п.).\n\nПо решению высшего органа ассоциации (союза) полномочия органа ассоциации (союза) могут быть досрочно прекращены в случаях грубого нарушения этим органом своих обязанностей, обнаружившейся неспособности к надлежащему ведению дел или при наличии иных серьезных оснований.","article_title":"Статья 123.10. Особенности управления в ассоциации (союзе)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"613a2f8606a79d8b5d5b3e91acf83e229bb1a0ea9dad41f9e4c14d1eba621252"},{"code_id":"GK_RF","article_number":"123.11","version_date":"1994-11-30","article_text":"1. Член ассоциации (союза) осуществляет корпоративные права, предусмотренные пунктом 1 статьи 652 настоящего Кодекса, в порядке, установленном в соответствии с законом уставом ассоциации (союза). Он также вправе на равных начала\n\nх с другими членами ассоциации (союза) безвозмездно, если иное не предусмотрено законом, пользоваться оказываемыми ею услугами.\n\nЧлен ассоциации (союза) вправе выйти из нее по своему усмотрению в любое время.\n\n2. Члены ассоциации (союза) наряду с обязанностями, предусмотренными для участников корпорации пунктом 4 статьи 652 настоящего Кодекса, также обязаны уплачивать предусмотренные уставом членские взносы и по решению высшего органа ассоциации (союза) вносить дополнительные имущественные взносы в имущество ассоциации (союза).\n\nЧлен ассоциации (союза) может быть исключен из нее в случаях и в порядке, которые установлены в соответствии с законом уставом ассоциации (союза).\n\n3. Членство в ассоциации (союзе) неотчуждаемо. Последствия прекращения членства в ассоциации (союзе) устанавливаются законом и (или) ее уставом.","article_title":"Статья 123.11. Права и обязанности члена ассоциации (союза)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6fbb7cdf2ffb826c839d54d56d23cf0ae75f25b830ecccf9a5c98f661b12d301"},{"code_id":"GK_RF","article_number":"123.13","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 24.07.2023 № 351-ФЗ)","article_title":"Статья 123.13. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd4cbf9cf97c77feea238cec2aabfc0a007ff534dc9873839ddcd91264224d97"},{"code_id":"GK_RF","article_number":"123.14","version_date":"1994-11-30","article_text":"1. К исключительной компетенции высшего органа товарищества собственников недвижимости наряду с вопросами, указанными в пункте 2 статьи 653 настоящего Кодекса, относится также принятие решений об установлении размера обязательных платежей и взносов членов товарищества.\n\n2. В товариществе собственников недвижимости создаются единоличный исполнительный орган (председатель) и постоянно действующий коллегиальный исполнительный орган (правление).\n\nПо решению высшего органа товарищества собственников недвижимости (пункт 1 статьи 653) полномочия постоянно действующих органов товарищества могут быть досрочно прекращены в случаях грубого нарушения ими своих обязанностей, обнаружившейся неспособности к надлежащему ведению дел или при наличии иных серьезных оснований.","article_title":"Статья 123.14. Особенности управления в товариществе собственников недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4117f87d0b43309c05529ebcdb850f7a10912954e8fdc76318a5bdf1e2a707f"},{"code_id":"GK_RF","article_number":"123.15","version_date":"1994-11-30","article_text":"1. Казачьими обществами признаются внесенные в государственный реестр казачьих обществ в Российской Федерации объединения граждан, созданные в целях сохранения традиционных образа жизни, хозяйствования и культуры российского казачества, а также в иных целях, предусмотренных Федеральным законом от 5 декабря 2005 года № 154-ФЗ \"О государственной службе российского казачества\", добровольно принявших на себя в порядке, установленном законом, обязательства по несению государственной или иной службы.\n\n2. Казачье общество по решению его членов может быть преобразовано в ассоциацию (союз) или автономную некоммерческую организацию.\n\n3. Положения настоящего Кодекса о некоммерческих организациях применяются к казачьим обществам, внесенным в государственный реестр казачьих обществ в Российской Федерации, если иное не установлено Федеральным законом от 5 декабря 2005 года № 154-ФЗ \"О государственной службе российского казачества\".","article_title":"Статья 123.15. Казачье общество, внесенное в государственный реестр казачьих обществ в Российской Федерации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9254eda9c834afb91667afbb43762d6157752e8ee480fff0ad3c2b3bc0fbde7c"},{"code_id":"GK_RF","article_number":"123.16","version_date":"1994-11-30","article_text":"1. Общинами коренных малочисленных народов Российской Федерации признаются добровольные объединения граждан, относящихся к коренным малочисленным народам Российской Федерации и объединившихся по кровнородственному и (или) территориально-соседскому признаку в целях защиты исконной среды обитания, сохранения и развития традиционных образа жизни, хозяйствования, промыслов и культуры.\n\n2. Члены общины коренных малочисленных народов Российской Федерации имеют право на получение части ее имущества или компенсации стоимости такой части при выходе из общины или ее ликвидации в порядке, установленном законом.\n\n3. Община коренных малочисленных народов Российской Федерации по решению ее членов может быть преобразована в ассоциацию (союз) или автономную некоммерческую организацию.\n\n4. Положения настоящего Кодекса о некоммерческих организациях применяются к общинам коренных малочисленных народов Российской Федерации, если иное не установлено законом.\n\n(Дополнение подпараграфом - Федеральный закон от 13.07.2015 № 268-ФЗ)","article_title":"Статья 123.16. Община коренных малочисленных народов Российской Федерации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27d8b8946dd80d324cd036d7833ae871b261483a6c5f48355fdea386ecbe3088"},{"code_id":"GK_RF","article_number":"123.16-1","version_date":"1994-11-30","article_text":"1. Адвокатскими палатами признаются некоммерческие организации, основанные на обязательном членстве и созданные в виде адвокатской палаты субъекта Российской Федерации или Федеральной палаты адвокатов Российской Федерации для реализации целей, предусмотренных законодательством об адвокатской деятельности и адвокатуре.\n\n2. Адвокатская палата субъекта Российской Федерации является некоммерческой организацией, основанной на обязательном членстве всех адвокатов одного субъекта Российской Федерации.\n\n3. Федеральная палата адвокатов Российской Федерации является некоммерческой организацией, объединяющей адвокатские палаты субъектов Российской Федерации на основе обязательного членства.\n\n4. Особенности создания, правового положения и деятельности адвокатских палат субъектов Российской Федерации и Федеральной палаты адвокатов Российской Федерации определяются законодательством об адвокатской деятельности и адвокатуре.\n\n(Дополнение подпараграфом - Федеральный закон от 13.07.2015 № 268-ФЗ)","article_title":"Статья 123.16-1. Адвокатские палаты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a59ad3726f3a57469c793f0b9b11dbca04f084ec2b861740db40e4d8da60eaa"},{"code_id":"GK_RF","article_number":"123.16-2","version_date":"1994-11-30","article_text":"1. Адвокатскими образованиями, являющимися юридическими лицами, признаются некоммерческие организации, созданные в соответствии с законодательством об адвокатской деятельности и адвокатуре в целях осуществления адвокатами адвокатской деятельности.\n\n2. Адвокатские образования, являющиеся юридическими лицами, создаются в виде коллегии адвокатов, адвокатского бюро или юридической консультации.\n\n3. Особенности создания, правового положения и деятельности адвокатских образований, являющихся юридическими лицами, определяются законодательством об адвокатской деятельности и адвокатуре.\n\n(Дополнение подпараграфом - Федеральный закон от 07.02.2017 № 12-ФЗ)","article_title":"Статья 123.16-2. Адвокатские образования, являющиеся юридическими лицами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ad801c5b0422ce8e1cbabe229b8e1c090f2627aaba737fb85c6832528702ba1"},{"code_id":"GK_RF","article_number":"123.16-3","version_date":"1994-11-30","article_text":"1. Нотариальными палатами признаются некоммерческие организации, которые представляют собой профессиональные объединения, основанные на обязательном членстве, и созданы в виде нотариальной палаты субъекта Российской Федерации или Федеральной нотариальной палаты для реализации целей, предусмотренных законодательством о нотариате.\n\n2. Нотариальная палата субъекта Российской Федерации является некоммерческой организацией, представляющей собой профессиональное объединение, основанное на обязательном членстве нотариусов, занимающихся частной практикой.\n\n3. Федеральная нотариальная палата является некоммерческой организацией, представляющей собой профессиональное объединение нотариальных палат субъектов Российской Федерации, основанное на их обязательном членстве.\n\n4. Особенности создания, правового положения и деятельности нотариальных палат субъектов Российской Федерации и Федеральной нотариальной палаты определяются законодательством о нотариате.\n\n(Дополнение параграфом - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n1. Общественно полезные фонды\n\n(Наименование в редакции Федерального закона от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.16-3. Нотариальные палаты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"464eb90637c0a06dc536bcd263592bc7e5fd4b9ff59bfb37338de22fa8b171ba"},{"code_id":"GK_RF","article_number":"123.17","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.17. Основные положения об общественно полезном фонде","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe5558663054b58a3bf000c6fc4ef8902427b4c07d7b55bb8dde007924e80b5f"},{"code_id":"GK_RF","article_number":"123.18","version_date":"1994-11-30","article_text":"1. Имущество, переданное фонду его учредителями (учредителем), является собственностью фонда. Учредители фонда не имеют имущественных прав в отношении созданного ими фонда и не отвечают по его обязательствам, а фонд не отвечает по обязательствам своих учредителей.\n\n2. Фонд использует имущество для целей, определенных в его уставе.\n\nЕжегодно фонд обязан опубликовывать отчеты об использовании своего имущества.","article_title":"Статья 123.18. Имущество фонда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2323157dffededc0213007889ace3d56720dfcfcdf7111cdeaebb71cf5a77386"},{"code_id":"GK_RF","article_number":"123.19","version_date":"1994-11-30","article_text":"определение приоритетных направлений деятельности фонда, принципов образования и использования его имущества;\n\nобразование других органов фонда и досрочное прекращение их полномочий;\n\nутверждение годовых отчетов и годовой бухгалтерской (финансовой) отчетности фонда;\n\nпринятие решений о создании фондом хозяйственных обществ и (или) об участии в них фонда, за исключением случаев, когда уставом фонда принятие решений по указанным вопросам отнесено к компетенции иных коллегиальных органов фонда; (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\nпринятие решений о создании филиалов и (или) об открытии представительств фонда;\n\nизменение устава фонда, если эта возможность предусмотрена уставом;\n\nодобрение совершаемых фондом сделок в случаях, предусмотренных законом.\n\nЗаконом или уставом фонда к исключительной компетенции высшего коллегиального органа фонда может быть отнесено принятие решений по иным вопросам.\n\nК компетенции единоличного исполнительного и (или) коллегиальных органов фонда относится решение вопросов, не входящих в исключительную компетенцию высшего коллегиального органа фонда. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 123.19. Управление фондом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ba8c0913ac74197a98b016d0615106bee5878c9e78a00d0438b6bceda9bf91b"},{"code_id":"GK_RF","article_number":"123.2","version_date":"1994-11-30","article_text":"Наименование потребительского кооператива должно содержать указание на основную цель его деятельности, а также слово \"кооператив\". Наименование общества взаимного страхования должно содержать слова \"потребительское общество\".","article_title":"Статья 123.2. Основные положения о потребительском кооперативе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f83e3b3a784701ce361cb5c4755a9243495e5a5649a276be76da4b8233d3d50"},{"code_id":"GK_RF","article_number":"123.20","version_date":"1994-11-30","article_text":"1. Устав фонда может быть изменен высшим коллегиальным органом фонда, если уставом не предусмотрена возможность его изменения по решению учредителя.\n\nУстав фонда может быть изменен решением суда, принятым по заявлению органов фонда или государственного органа, уполномоченного осуществлять надзор за деятельностью фонда, в случае, если сохранение устава фонда в неизменном виде влечет последствия, которые было невозможно предвидеть при учреждении фонда, а высший коллегиальный орган фонда или учредитель фонда не изменяет его устав.\n\n2. Фонд может быть ликвидирован только на основании решения суда, принятого по заявлению заинтересованных лиц, в случае, если:\n\n1) имущества фонда недостаточно для осуществления его целей и вероятность получения необходимого имущества нереальна;\n\n2) цели фонда не могут быть достигнуты, а необходимые изменения целей фонда не могут быть произведены;\n\n3) фонд в своей деятельности уклоняется от целей, предусмотренных уставом;\n\n4) в других случаях, предусмотренных законом.\n\n3. В случае ликвидации фонда его имущество, оставшееся после удовлетворения требований кредиторов, направляется на цели, указанные в уставе фонда, за исключением случаев, если законом предусмотрен возврат такого имущества учредителям фонда.","article_title":"Статья 123.20. Изменение устава и ликвидация фонда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c395fbf26a262368a5a9259091497e35db0e7637c06b8b177b3865a1b37b7c9"},{"code_id":"GK_RF","article_number":"123.20-1","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 29.07.2017 № 259-ФЗ) (Утратила силу  - Федеральный закон от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.20-1. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e64c0dc3284fd40b547595aba12b1366ede64ab854788f0cab6b5d658e6f3d7"},{"code_id":"GK_RF","article_number":"123.20-2","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 29.07.2017 № 259-ФЗ) (Утратила силу  - Федеральный закон от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.20-2. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e64c0dc3284fd40b547595aba12b1366ede64ab854788f0cab6b5d658e6f3d7"},{"code_id":"GK_RF","article_number":"123.20-3","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 29.07.2017 № 259-ФЗ) (Утратила силу  - Федеральный закон от 01.07.2021 № 287-ФЗ)\n\n11. Личные фонды\n\n(Дополнение подпараграфом - Федеральный закон от 01.07.2021 № 287-ФЗ)","article_title":"Статья 123.20-3. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8a6c18d3f3cdd0ce2a5b920ae5669d010fce9239b14a505069a11e9219fcb7b"},{"code_id":"GK_RF","article_number":"123.20-4","version_date":"1994-11-30","article_text":"Учредитель личного фонда вправе предусмотреть в уставе созданного при его жизни личного фонда, что после его смерти такой личный фонд продолжает свою деятельность в соответствии с утвержденным учредителем уставом и условиями управления, при этом такой личный фонд не может быть после смерти его учредителя ликвидирован по решению его органов.\n\nЗамена учредителя личного фонда не допускается. При создании личных фондов не допускается соучредительство нескольких лиц, за исключением случаев, если учредителями личного фонда являются супруги, передающие личному фонду общее имущество (статья 256).\n\nСтоимость имущества, передаваемого личному фонду (за исключением наследственного фонда) его учредителем при создании личного фонда, не может быть менее ста миллионов рублей, при этом стоимость этого имущества определяется на основании оценки его рыночной стоимости.\n\nУчредитель личного фонда вправе утвердить условия управления личным фондом и иные внутренние документы личного фонда, обязательные для всех органов личного фонда.\n\nУстав личного фонда и условия управления личным фондом подлежат нотариальному удостоверению.\n\nЕсли иное не установлено настоящим Кодексом или уставом личного фонда, информация о содержании условий управления личным фондом и содержании иных внутренних документов личного фонда не подлежит раскрытию и является конфиденциальной.\n\nЕсли иное не предусмотрено уставом личного фонда, устав личного фонда, условия управления личным фондом и иные внутренние документы личного фонда при жизни учредителя фонда могут быть им изменены. После смерти учредит\n\nеля личного фонда утвержденные учредителем при его жизни устав личного фонда, условия управления личным фондом и иные внутренние документы личного фонда не могут быть изменены, за исключением изменения на основании решения суда по требованию любого органа личного фонда в случаях, если управление таким фондом на прежних условиях стало невозможно по обстоятельствам, возникновение которых при создании такого фонда нельзя было предполагать. (В редакции  Федерального закона от 08.08.2024 № 237-ФЗ)\n\nУстав наследственного фонда и условия управления наследственным фондом не могут быть изменены после создания наследственного фонда, за исключением изменения на основании решения суда по требованию любого органа наследственного фонда в случаях, если управление наследственным фондом на прежних условиях стало невозможно по обстоятельствам, возникновение которых при создании наследственного фонда нельзя было предполагать, а также в случае, если будет установлено, что выгодоприобретатель наследственного фонда является недостойным наследником (статья 1117), если только это обстоятельство не было известно в момент создания наследственного фонда.\n\n10. Реорганизация личного фонда (за исключением наследственного фонда) допускается в форме слияния, присоединения, разделения, выделения при условии, что в результате такой реорганизации образуются личный фонд или личные фонды, созданные тем же учредителем. При жизни учредителя личного фонда допускается также преобразование личного фонда в общественно полезный фонд по решению учредителя.\n\nРеорганизация личного фонда после смерти его учредителя не допускается, за исключением преобразования личного фонда в общественно полезный фонд в случаях, предусмотренных условиями управления личным фондом и пунктом 6 статьи 12320-5 настоящего Кодекса.\n\n11. Ликвидация личного фонда осуществляется по решению суда:\n\n1) в порядке и по основаниям, предусмотренным подпунктами 1 - 4 пункта 3 статьи 61 настоящего Кодекса, а также по иску уполномоченного государственного органа в случае осуществления личным фондом деятельности, указанной в законодательстве Российской Федерации об иностранных агентах; (В редакции  Федерального закона от 08.08.2024 № 237-ФЗ)\n\n2) по требованию единоличного исполнительного органа личного фонда в связи с наступлением срока, до истечения которого создавался личный фонд;\n\n3) по требованию единоличного исполнительного органа личного фонда в связи с наступлением указанных в условиях управления личным фондом обстоятельств;\n\n4) по требованию выгодоприобретателя личного фонда в случае невозможности формирования органов личного фонда (отсутствие кворума в коллегиальных органах, отсутствие единоличного исполнительного органа);\n\n5) по требованию единоличного исполнительного органа личного фонда в связи с невозможностью на протяжении трех лет, если иной срок не предусмотрен уставом личного фонда, выполнить предусмотренные учредителем личного фонда условия, в соответствии с которыми подлежат определению выгодоприобретатели личного фонда.\n\nОставшееся после ликвидации личного фонда имущество подлежит передаче выгодоприобретателям личного фонда соразмерно объему их прав на получение имущества или дохода от деятельности личного фонда, если условиями управления личным фондом не предусмотрены иные правила распределения оставшегося имущества, в том числе его передача лицам, не являющимся выгодоприобретателями. При отсутствии возможности определить лиц, которым подлежит передаче оставшееся после ликвидации личного фонда имущество, такое имущество подлежит передаче в собственность учредителя (учредителей) личного фонда, а если к этому моменту брак между учредителями, передавшими фонду общее имущество, расторгнут, - в общую долевую собственность учредителей, доли которых в передаваемом им имуществе признаются равными, если иное не установлено соглашением между ними или решением суда. При отсутствии возможности определить лиц, которым подлежит передаче оставшееся после ликвидации наследственного фонда имущество, такое имущество подлежит передаче в соответствии с решением суда в собственность Российской Федерации. (В редакции  Федерального закона от 08.08.2024 № 237-ФЗ)\n\n12. Отчет об использовании имущества личного фонда не подлежит опубликованию, за исключением случаев, предусмотренных условиями управления личным фондом.","article_title":"Статья 123.20-4. Основные положения о личном фонде","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"270d119f925487035f39e711afe564bbd4176135809f8af72f4e1c0ddb5012c4"},{"code_id":"GK_RF","article_number":"123.20-5","version_date":"1994-11-30","article_text":"1. Условия управления личным фондом могут включать в себя положения о передаче определенным лицам (выгодоприобретателям личного фонда) или отдельным категориям лиц из неопределенного круга лиц (далее - отдельные категории лиц) всего имущества личного фонда или его части, в том числе при наступлении обстоятельств, относительно которых неизвестно, наступят они или нет.\n\n2. Условиями управления личным фондом может быть предусмотрено, что выгодоприобретатели личного фонда или отдельные категории лиц, которым подлежит передаче имущество личного фонда, определяются органами личного фонда в соответствии с условиями управления личным фондом.\n\n3. Порядок передачи выгодоприобретателям личного фонда или отдельным категориям лиц всего имущества личного фонда или его части, в том числе доходов от деятельности личного фонда, должен быть определен условиями управления личным фондом путем указания на вид и размер передаваемого имущества или порядок определения вида и размера имущества, в том числе имущественного права (например, права пользования имуществом, права на оплату работ, услуг, оказываемых третьими лицами выгодоприобретателям личного фонда или отдельным категориям лиц), срок или периодичность передачи имущества, а также на обстоятельства, при наступлении которых осуществляется такая передача.\n\n4. Выгодоприобретателями личного фонда могут быть любые участники регулируемых гражданским законодательством отношений, за исключением коммерческих юридических лиц. Учредитель личного фонда не может быть выгодоприобретателем личного фонда, если иное не предусмотрено уставом этого фонда.\n\n5. Выгодоприобретатель личного фонда вправе потребовать от личного фонда, а выгодоприобретатель наследственного фонда вправе потребовать от нотариуса или наследственного фонда ознакомить их с той частью условий управления личным фондом, в которой содержатся порядок определения и назначения органов личного фонда, положения о передаче этому выгодоприобретателю всего или части имущества личного фонда, а также описание обстоятельств, при наступлении которых осуществляется такая передача.\n\n6. Не позднее шести месяцев со дня смерти гражданина, учредившего личный фонд при жизни, если условия управления этим фондом после смерти учредителя предусматривают исключительно положения о передаче отдельным категориям лиц из неопределенного круга лиц всего имущества личного фонда или его части, такой фонд подлежит преобразованию в общественно полезный фонд (статья 12317), при этом устав личного фонда, условия управления личным фондом и иные внутренние документы личного фонда, утвержденные его учредителем, не подлежат изменению, а в едином государственном реестре юридических лиц отражаются сведения о новом наименовании этого фонда и об изменении его организационно-правовой формы.","article_title":"Статья 123.20-5. Условия управления личным фондом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd62cbad7c0ce64a12517727c2f7b62936ae4720258c1864b0bc6009d357588e"},{"code_id":"GK_RF","article_number":"123.20-6","version_date":"1994-11-30","article_text":"1. Выгодоприобретатель личного фонда имеет право на получение имущества в соответствии с условиями управления личным фондом, а также иные права, предусмотренные настоящим Кодексом.\n\nПрава выгодоприобретателя личного фонда не могут переходить к другим лицам, в том числе в случае универсального правопреемства, за исключением случаев преобразования выгодоприобретателя - юридического лица, если условиями управления личным фондом не предусмотрено прекращение прав такого выгодоприобретателя при его преобразовании. На права выгодоприобретателя личного фонда, в том числе выгодоприобретателя наследственного фонда, не может быть обращено взыскание по обязательствам такого выгодоприобретателя. Сделки, совершенные с нарушением этих правил, являются ничтожными.\n\n2. Права гражданина-выгодоприобретателя наследственного фонда не переходят по наследству. Права выгодоприобретателя - юридического лица наследственного фонда прекращаются в случае реорганизации выгодоприобретателя - юридического лица, за исключением случая преобразования, если условиями управления наследственным фондом не предусмотрено прекращение прав такого выгодоприобретателя при его преобразовании.\n\nПосле смерти гражданина-выгодоприобретателя или ликвидации выгодоприобретателя - юридического лица, а также в случае заявленного наследственному фонду в нотариальной форме отказа выгодоприобретателя наследственного фонда от права на получение имущества новые выгодоприобретатели наследственного фонда определяются в соответствии с условиями управления наследственным фондом, в частности, они могут быть определены путем подназначения.\n\n3. В случаях, предусмотренных уставом личного фонда, выгодоприобретатель вправе запрашивать и получать у личного фонда информацию о деятельности личного фонда.\n\n4. Выгодоприобретатель личного фонда вправе потребовать проведения аудита деятельности личного фонда выбранным им аудитором. В случае проведения такого аудита оплата услуг аудитора осуществляется за счет выгодоприобретателя личного фонда, по требованию которого он проводится. Расходы выгодоприобретателя личного фонда на оплату услуг аудитора могут быть ему возмещены по решению попечительского совета за счет средств такого фонда.\n\n5. В случае нарушения условий управления личным фондом, повлекшего возникновение у выгодоприобретателя личного фонда убытков, последний вправе потребовать их возмещения, если это право предусмотрено уставом личного фонда.\n\n6. Выгодоприобретатель не отвечает по обязательствам личного фонда, а личный фонд не отвечает по обязательствам выгодоприобретателя.","article_title":"Статья 123.20-6. Права выгодоприобретателя личного фонда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27341143b96ce0cbed139f1e2c9bcd297a30c3dfab8d701821dc1006c3884ad7"},{"code_id":"GK_RF","article_number":"123.20-7","version_date":"1994-11-30","article_text":"После смерти гражданина, учредившего личный фонд при жизни, органы личного фонда формируются и изменяются в соответствии с уставом и условиями управления этого фонда, при этом лица, входящие в состав органов личного фонда или имеющие право войти в состав органов этого фонда, а также выгодоприобретатели этого фонда вправе требовать формирования и изменения органов личного фонда в соответствии с его уставом и условиями управления личным фондом. Уставом личного фонда и условиями управления личным фондом может быть предусмотрен порядок определения членов коллегиальных органов личного фонда и лица, осуществляющего полномочия единоличного исполнительного органа личного фонда, в случае их выбытия, в том числе предусмотрено подназначение указанных лиц из определенного списка.\n\nВыгодоприобретатель наследственного фонда не может выступать в качестве единоличного исполнительного органа наследственного фонда или члена коллегиального исполнительного органа наследственного фонда.\n\nУставом личного фонда может быть также предусмотрено создание надзорного органа личного фонда, полномочия которого состоят в осуществлении надзора за деятельностью органов личного фонда, в согласовании совершения личным фондом определенных в уставе юридически значимых действий и (или) в принятии решения о досрочном прекращении полномочий единоличного исполнительного органа личного фонда, нарушившего свою обязанность действовать добросовестно или разумно в интересах личного фонда и (или) его выгодоприобретателей, и о назначении временного единоличного исполнительного органа личного фонда.","article_title":"Статья 123.20-7. Управление личным фондом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"49ddf47c99b235d7faf0de5e963e8c32745b0a1cff81173fc0cf201013c9548c"},{"code_id":"GK_RF","article_number":"123.20-8","version_date":"1994-11-30","article_text":"1. После смерти гражданина, который предусмотрел в своем завещании создание наследственного фонда, такой наследственный фонд подлежит созданию по заявлению, направляемому в уполномоченный государственный орган нотариусом, ведущим наследственное дело, с приложением к заявлению составленного при жизни указанного гражданина его решения об учреждении наследственного фонда и утвержденного этим гражданином устава фонда и после его создания призывается к наследованию по завещанию в порядке, предусмотренном разделом V настоящего Кодекса.\n\nНаследственный фонд может быть создан на основании решения суда по требованию душеприказчика или выгодоприобретателя наследственного фонда в случае неисполнения нотариусом обязанности по созданию наследственного фонда.\n\nНотариус, ведущий наследственное дело, обязан направить в уполномоченный государственный орган заявление о государственной регистрации наследственного фонда не позднее трех рабочих дней со дня открытия наследственного дела после смерти гражданина, который предусмотрел в своем завещании создание наследственного фонда. Наследственный фонд не подлежит регистрации по истечении одного года со дня открытия наследства.\n\nДействия нотариуса по созданию наследственного фонда могут быть оспорены выгодоприобретателями наследственного фонда, душеприказчиком или наследниками, если нотариусом нарушены содержащиеся в завещании или решении об учреждении наследственного фонда распоряжения наследодателя относительно создания наследственного фонда и условий управления им.\n\n2. При создании наследственного фонда нотариус, получивший от наследственного фонда заявление о принятии наследства, обязан выдать такому фонду свидетельство о праве на наследство в срок, указанный в решении об учреждении наследственного фонда, но не позднее срока, предусмотренного статьей 1154 настоящего Кодекса. В случае неисполнения нотариусом указанных обязанностей наследственный фонд вправе обжаловать бездействие нотариуса.\n\n3. До направления нотариусом указанного в абзаце третьем пункта 1 настоящей статьи заявления о государственной регистрации наследственного фонда в уполномоченный государственный орган нотариус предлагает лицам, указанным в решении об учреждении наследственного фонда, или лицам, которые могут быть определены в порядке, установленном решением об учреждении наследственного фонда, войти в состав органов наследственного фонда. При согласии указанных лиц войти в состав органов наследственного фонда нотариус направляет сведения о них в уполномоченный государственный орган.\n\nВ случае отказа лица, указанного в решении об учреждении наследственного фонда, войти в состав органов наследственного фонда и невозможности сформировать органы наследственного фонда в соответствии с решением об учреждении наследственного фонда нотариус не вправе направлять в уполномоченный государственный орган заявление о создании наследственного фонда.\n\n4. Замена членов коллегиальных органов наследственного фонда и лица, осуществляющего полномочия единоличного исполнительного органа наследственного фонда, осуществляется в порядке, предусмотренном уставом наследственного фонда. Уставом наследственного фонда может быть предусмотрен порядок определения членов коллегиальных органов наследственного фонда и лица, осуществляющего полномочия единоличного исполнительного органа наследственного фонда, в случае их выбытия, в том числе предусмотрено подназначение указанных лиц из определенного списка.\n\n5. Условия управления наследственным фондом должны включать в себя положения, указанные в пунктах 1 и 3 статьи 12320-5 настоящего Кодекса.\n\nУсловия управления наследственным фондом до направления нотариусом указанного в абзаце третьем пункта 1 настоящей статьи заявления доводятся им до сведения лиц, входящих в состав органов наследственного фонда, и могут быть раскрыты только выгодоприобретателям в соответствии с пунктом 5 статьи 12320-5 настоящего Кодекса, а также в предусмотренных законом случаях органам государственной власти и органам местного самоуправления.\n\n6. Единоличный исполнительный орган наследственного фонда обязан хранить устав наследственного фонда и внесенные в него изменения и дополнения, которые зарегистрированы в установленном порядке, решение об учреждении наследственного фонда, документы, подтверждающие права наследственного фонда на его имущество, документ, содержащий условия управления наследственным фондом, годовые отчеты, документы бухгалтерского учета, документы бухгалтерской (финансовой) отчетности, протоколы собраний коллегиальных органов наследственного фонда, отчеты оценщиков, заключения ревизионной комиссии (ревизора) наследственного фонда, аудитора наследственного фонда, государственных и муниципальных органов финансового контроля, судебные акты по спорам, связанным с управлением наследственным фондом, иные документы, предусмотренные настоящим Кодексом, уставом наследственного фонда и условиями управления наследственным фондом.\n\nУставом наследственного фонда может быть предусмотрено хранение документов, указанных в абзаце первом настоящего пункта, у нотариуса по правилам, предусмотренным законодательством о нотариате.\n\n2. Учреждения","article_title":"Статья 123.20-8. Создание наследственного фонда и управление им","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e154248b11e5683a562d64a70b82a501255f186486a2d96919b9843abc8dec83"},{"code_id":"GK_RF","article_number":"123.21","version_date":"1994-11-30","article_text":"1. Учреждением признается унитарная некоммерческая организация, созданная собственником для осуществления управленческих, социально-культурных или иных функций некоммерческого характера.\n\nУчредитель является собственником имущества созданного им учреждения. На имущество, закрепленное собственником за учреждением и приобретенное учреждением по иным основаниям, оно приобретает право оперативного управления в соответствии с настоящим Кодексом.\n\n2. Учреждение может быть создано гражданином или юридич\n\nеским лицом (частное учреждение) либо соответственно Российской Федерацией, субъектом Российской Федерации, муниципальным образованием (государственное учреждение, муниципальное учреждение).\n\nПри создании учреждения не допускается соучредительство нескольких лиц.\n\n3. Учреждение отвечает по своим обязательствам находящимися в его распоряжении денежными средствами, а в случаях, установленных законом, также иным имуществом. При недостаточности указанных денежных средств или имущества субсидиарную ответственность по обязательствам учреждения в случаях, предусмотренных пунктами 4 - 6 статьи 12322 и пунктом 2 статьи 12323 настоящего Кодекса, несет собственник соответствующего имущества.\n\n4. Учредитель учреждения назначает его руководителя, являющегося органом учреждения. В случаях и в порядке, которые предусмотрены законом, руководитель государственного или муниципального учреждения может избираться его коллегиальным органом и утверждаться его учредителем.\n\nПо решению учредителя в учреждении могут быть созданы коллегиальные органы, подотчетные учредителю. Компетенция коллегиальных органов учреждения, порядок их создания и принятия ими решений определяются законом и уставом учреждения.","article_title":"Статья 123.21. Основные положения об учреждениях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c77b00705ce4b524971389eec4bd4ee7ab985c475556466795703d903075cc6"},{"code_id":"GK_RF","article_number":"123.22","version_date":"1994-11-30","article_text":"1. Государственное или муниципальное учреждение может быть казенным, бюджетным или автономным учреждением.\n\n2. Порядок финансового обеспечения деятельности государственных и муниципальных учреждений определяется законом.\n\n3. Государственные и муниципальные учреждения не отвечают по обязательствам собственников своего имущества.\n\n4. Казенное учреждение отвечает по своим обязательствам находящимися в его распоряжении денежными средствами. При недостаточности денежных средств субсидиарную ответственность по обязательствам казенного учреждения несет собственник его имущества.\n\n5. Бюджетное учреждение отвечает по своим обязательствам всем находящимся у него на праве оперативного управления имуществом, в том числе приобретенным за счет доходов, полученных от приносящей доход деятельности, за исключением особо ценного движимого имущества, закрепленного за бюджетным учреждением собственником этого имущества или приобретенного бюджетным учреждением за счет средств, выделенных собственником его имущества, а также недвижимого имущества независимо от того, по каким основаниям оно поступило в оперативное управление бюджетного учреждения и за счет каких средств оно приобретено.\n\nПо обязательствам бюджетного учреждения, связанным с причинением вреда гражданам, при недостаточности имущества учреждения, на которое в соответствии с абзацем первым настоящего пункта может быть обращено взыскание, субсидиарную ответственность несет собственник имущества бюджетного учреждения.\n\nВ случае ликвидации бюджетного учреждения при недостаточности имущества бюджетного учреждения, на которое в соответствии с абзацем первым настоящего пункта может быть обращено взыскание, субсидиарную ответственность по обязательствам бюджетного учреждения, вытекающим из публичного договора, несет собственник имущества бюджетного учреждения. (Дополнение абзацем - Федеральный закон от 11.03.2024 № 48-ФЗ)\n\n6. Автономное учреждение отвечает по своим обязательствам всем находящимся у него на праве оперативного управления имуществом, за исключением недвижимого имущества и особо ценного движимого имущества, закрепленных за автономным учреждением собственником этого имущества или приобретенных автономным учреждением за счет средств, выделенных собственником его имущества.\n\nПо обязательствам автономного учреждения, связанным с причинением вреда гражданам, при недостаточности имущества учреждения, на которое в соответствии с абзацем первым настоящего пункта может быть обращено взыскание, субсидиарную ответственность несет собственник имущества автономного учреждения.\n\nВ случае ликвидации автономного учреждения при недостаточности имущества автономного учреждения, на которое в соответствии с абзацем первым настоящего пункта может быть обращено взыскание, субсидиарную ответственность по обязательствам автономного учреждения, вытекающим из публичного договора, несет собственник имущества автономного учреждения. (Дополнение абзацем - Федеральный закон от 11.03.2024 № 48-ФЗ)\n\nЕжегодно автономное учреждение обязано опубликовывать отчеты о своей деятельности и об использовании закрепленного за ним имущества.\n\n7. Государственное или муниципальное учреждение может быть преобразовано в некоммерческую организацию иных организационно-правовых форм в случаях, предусмотренных законом.\n\n8. Особенности правового положения государственных и муниципальных учреждений отдельных типов определяются законом.","article_title":"Статья 123.22. Государственное учреждение и муниципальное учреждение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e7191aea6440779015b86106e405c64e2ce9fab7672797cb0d5c3702388548c8"},{"code_id":"GK_RF","article_number":"123.23","version_date":"1994-11-30","article_text":"1. Частное учреждение полностью или частично финансируется собственником его имущества.\n\n2. Частное учреждение отвечает по своим обязательствам находящимися в его распоряжении денежными средствами. При недостаточности указанных денежных средств субсидиарную ответственность по обязательствам частного учреждения несет собственник его имущества.\n\n3. Частное учреждение может быть преобразовано учредителем в автономную некоммерческую организацию или фонд.\n\n3. Автономные некоммерческие организации","article_title":"Статья 123.23. Частное учреждение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"abcaca968491f93efd19d42b3d4429a1d681191545f3d30a40da9444fe1833e5"},{"code_id":"GK_RF","article_number":"123.24","version_date":"1994-11-30","article_text":"1. Автономной некоммерческой организацией признается унитарная некоммерческая организация, не имеющая членства и созданная на основе имущественных взносов граждан и (или) юридических лиц в целях предоставления услуг в сферах образования, здравоохранения, культуры, науки и иных сферах некоммерческой деятельности.\n\nАвтономная некоммерческая организация может быть создана одним лицом (может иметь одного учредителя).\n\n2. Устав автономной некоммерческой организации должен содержать сведения о ее наименовании, включающем слова \"автономная некоммерческая организация\", месте нахождения, предмете и целях ее деятельности, составе, порядке образования и компетенции органов автономной некоммерческой организации, а также иные предусмотренные законом сведения.\n\n3. Имущество, переданное автономной некоммерческой организации ее учредителями, является собственностью автономной некоммерческой организации. Учредители автономной некоммерческой организации не сохраняют права на имущество, переданное ими в собственность этой организации.\n\nУчредители не отвечают по обязательствам созданной ими автономной некоммерческой организации, а она не отвечает по обязательствам своих учредителей.\n\n4. Учредители автономной некоммерческой организации могут пользоваться ее услугами только на равных условиях с другими лицами.\n\n5. Автономная некоммерческая организация вправе заниматься предпринимательской деятельностью, необходимой для достижения целей, ради которых она создана, и соответствующей этим целям, создавая для осуществления предпринимательской деятельности хозяйственные общества или участвуя в них.\n\n6. Лицо может по своему усмотрению выйти из состава учредителей автономной некоммерческой организации.\n\nПо решению учредителей автономной некоммерческой организации, принятому единогласно, в состав ее учредителей могут быть приняты новые лица.\n\n7. Автономная некоммерческая организация по решению своих учредителей может быть преобразована в фонд.\n\n8. В части, не урегулированной настоящим Кодексом, правовое положение автономных некоммерческих организаций, а также права и обязанности их учредителей устанавливаются законом.","article_title":"Статья 123.24. Основные положения об автономной некоммерческой организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"845466ed4206e5e20c904d2a41bc008e38badaed22d52574ae9bbb97a3a3f033"},{"code_id":"GK_RF","article_number":"123.25","version_date":"1994-11-30","article_text":"1. Управление деятельностью автономной некоммерческой организации осуществляют ее учредители в порядке, установленном ее уставом, утвержденным ее учредителями.\n\n2. По решению учредителей (учредителя) автономной некоммерческой организации в ней может быть создан постоянно действующий коллегиальный орган (органы), компетенция которого устанавливается уставом автономной некоммерческой организации.\n\n3. Учредители (учредитель) автономной некоммерческой организации назначают единоличный исполнительный орган автономной некоммерческой организации (председателя, генерального директора и т.п.). Единоличным исполнительным органом автономной некоммерческой организации может быть назначен один из ее учредителей-граждан.\n\n4. Религиозные организации","article_title":"Статья 123.25. Управление автономной некоммерческой организацией","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b97a70f84443e43ac5608c71de9741cf6abe12d61c175dc964c0beb87a28841"},{"code_id":"GK_RF","article_number":"123.26","version_date":"1994-11-30","article_text":"1. Религиозной организацией признается добровольное объединение постоянно и на законных основаниях проживающих на территории Российской Федерации граждан Российской Федерации или иных лиц, образованное ими в целях совместного исповедания и распространения веры и зарегистрированное в установленном законом порядке в качестве юридического лица (местная религиозная организация), объединение этих организаций (централизованная религиозная организация), а также созданная указанным объединением в соответствии с законом о свободе совести и о религиозных объединениях в целях совместного исповедания и распространения веры организация и (или) созданный указанным объединением руководящий или координирующий орган.\n\n2. Гражданско-правовое положение религиозных организаций определяется настоящим Кодексом и законом о свободе совести и о религиозных объединениях. Положения настоящего Кодекса применяются к религиозным организациям, если иное не установлено законом о свободе совести и о религиозных объединениях и другими законами.\n\nРелигиозные организации действуют в соответствии со своими уставами и внутренними установлениями, не противоречащими закону.\n\nПорядок образования органов религиозной организации и их компетенция, порядок принятия решений этими органами, а также отношения между религиозной организацией и лицами, входящими в состав ее органов, определяются в соответствии с законом о свободе совести и о религиозных объединениях уставом и внутренними установлениями религиозной организации.\n\n(Пункт в редакции Федерального закона от 06.04.2015 № 80-ФЗ)\n\n3. Религиозная организация не может быть преобразована в юридическое лицо другой организационно-правовой формы.","article_title":"Статья 123.26. Основные положения о религиозных организациях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b021a0d800de59d09ffb3078544435ebe1918ecc650c18e4bd41de428eb617b"},{"code_id":"GK_RF","article_number":"123.27","version_date":"1994-11-30","article_text":"1. Местная религиозная организация создается в соответствии с законом о свободе совести и о религиозных объединениях не менее чем десятью гражданами-учредителями, централизованная религиозная организация - не менее чем тремя местными религиозными организациями или другой централизованной религиозной организацией.\n\n2. Учредительным документом религиозной организации является устав, утвержденный ее учредителями или централизованной религиозной организацией.\n\nУстав религиозной организации должен содержать сведения о ее виде, наименовании и месте нахождения, предмете и целях ее деятельности, составе, компетенции ее органов и порядке принятия ими решений, об источниках образования ее имущества, о направлениях его использования и порядке распределения имущества, остающегося после ее ликвидации, а также иные сведения, предусмотренные законом о свободе совести и о религиозных объединениях.\n\n3. Учредитель (учредители) религиозной организации может выполнять функции органа управления или членов коллегиального органа управления данной религиозной организации в порядке, установленном в соответствии с законом о свободе совести и о религиозных объединениях уставом религиозной организации и внутренними установлениями.","article_title":"Статья 123.27. Учредители и устав религиозной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ce30545f535a9b432f45d53a88fdfe4c6f366817a4023ce26f8e2c13949b232"},{"code_id":"GK_RF","article_number":"123.28","version_date":"1994-11-30","article_text":"1. Религиозные организации являются собственниками принадлежащего им имущества, в том числе имущества, приобретенного или созданного ими за счет собственных средств, а также пожертвованного религиозным организациям или приобретенного ими по иным предусмотренным законом основаниям.\n\n2. На принадлежащее религиозным организациям имущество богослужебного назначения не может быть обращено взыскание по требованиям их кредиторов. Перечень такого имущества определяется в порядке, установленном законом о свободе совести и о религиозных объединениях.\n\n3. Учредители религиозной организации не сохраняют имущественные права на имущество, переданное ими этой организации в собственность.\n\n4. Учредители религиозных организаций не отвечают по обязательствам этих организаций, а эти организации не отвечают по обязательствам своих учредителей.","article_title":"Статья 123.28. Имущество религиозной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b35a8b64c2a4701fa15ff707600ee479da76c18968b7358be4bdb13bc0ec9cb2"},{"code_id":"GK_RF","article_number":"123.3","version_date":"1994-11-30","article_text":"1. В течение трех месяцев после утверждения ежегодного баланса члены потребительского кооператива обязаны покрыть образовавшиеся убытки путем внесения дополнительных взносов. В случае невыполнения этой обязанности кооператив может быть ликвидирован в судебном порядке по требованию кредиторов.\n\n2. Члены потребительского кооператива солидарно несут субсидиарную ответственность по его обязательствам в пределах невнесенной части дополнительного взноса каждого из членов кооператива.\n\n3. Общественные организации","article_title":"Статья 123.3. Обязанность членов потребительского кооператива по внесению дополнительных взносов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a8ac2e6c977c38c732698e149ae70dc91fb1e04fbcdce3e18595c9a0d0bdd6b"},{"code_id":"GK_RF","article_number":"123.4","version_date":"1994-11-30","article_text":"1. Общественными организациями признаются добровольные объединения граждан, объединившихся в установленном законом порядке на основе общности их интересов для удовлетворения духовных или иных нематериальных потребностей, для представления и защиты общих интересов и достижения иных не противоречащих закону целей.\n\n2. Общественная организация является собственником своего имущества. Ее участники (члены) не сохраняют имущественные права на переданное ими в собственность организации имущество, в том числе на членские взносы.\n\nУчастники (члены) общественной организации не отвечают по обязательствам организации, в которой участвуют в качестве членов, а организация не отвечает по обязательствам своих членов.\n\n3. Общественные организации могут объединяться в ассоциации (союзы) в порядке, установленном настоящим Кодексом.","article_title":"Статья 123.4. Основные положения об общественных организациях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02d9e078fd41933dbad265440c14a61587f828c787b1db70801880c0395e0d2c"},{"code_id":"GK_RF","article_number":"123.5","version_date":"1994-11-30","article_text":"1. Количество учредителей общественной организации не может быть менее трех.\n\n2. Устав общественной организации должен содержать сведения о ее наименовании и месте нахождения, предмете и целях ее деятельности, а также условия о порядке вступления (принятия) в общественную организацию и выхода из нее, составе и компетенции ее органов и порядке принятия ими решений, в том числе по вопросам, решения по которым принимаются единогласно или квалифицированным большинством голосов, об имущественных правах и обязанностях участника (члена) организации и о порядке распределения имущества, оставшегося после ликвидации организации.","article_title":"Статья 123.5. Учредители и устав общественной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22e215c2644528b82e6ccebd92cdef7e8527538e57f19ecd3b50666ea6708bf4"},{"code_id":"GK_RF","article_number":"123.6","version_date":"1994-11-30","article_text":"1. Участник (член) общественной организации осуществляет корпоративные права, предусмотренные пунктом 1 статьи 652 настоящего Кодекса, в порядке, установленном уставом организации. Он также вправе на равных началах с другими участниками (членами) организации безвозмездно пользоваться оказываемыми ею услугами.\n\n2. Участник (член) общественной организации наряду с обязанностями, предусмотренными для участников корпорации пунктом 4 статьи 652 настоящего Кодекса, также несет обязанность уплачивать предусмотренные ее уставом членские и иные имущественные взносы.\n\nУчастник (член) общественной организации по своему усмотрению в любое время вправе выйти из организации, в которой он участвует.\n\n3. Членство в общественной организации неотчуждаемо. Осуществление прав участника (члена) общественной организации не может быть передано другому лицу.","article_title":"Статья 123.6. Права и обязанности участника (члена) общественной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"faeaa338315ebfc0250e9b6533c36e2ca60f569ac847da2f93308b5852ee2345"},{"code_id":"GK_RF","article_number":"123.7","version_date":"1994-11-30","article_text":"1. К исключительной компетенции высшего органа общественной организации наряду с вопросами, указанными в пункте 2 статьи 653 настоящего Кодекса, относится также принятие решений о размере и порядке уплаты ее участниками (членами) членских и иных имущественных взносов.\n\n2. В общественной организации образуется единоличный исполнительный орган (председатель, президент и т.п.) и могут образовываться постоянно действующие коллегиальные исполнительные органы (совет, правление, президиум и т.п.).\n\nПо решению общего собрания членов общественной организации полномочия ее органа могут быть досрочно прекращены в случаях грубого нарушения этим органом своих обязанностей, обнаружившейся неспособности к надлежащему ведению дел или при наличии иных серьезных оснований.\n\n31. Общественные движения\n\n(Дополнение подпараграфом - Федеральный закон от 23.05.2015 № 133-ФЗ)","article_title":"Статья 123.7. Особенности управления в общественной организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ea8b5203b89522609dd237a181c39fefb5b5087d3dd9101c8d35aebac9caf68d"},{"code_id":"GK_RF","article_number":"123.7-1","version_date":"1994-11-30","article_text":"1. Общественным движением является состоящее из участников общественное объединение, преследующее социальные, политические и иные общественно полезные цели, поддерживаемые участниками общественного движения.\n\n2. Положения настоящего Кодекса о некоммерческих организациях применяются к общественным движениям, если иное не предусмотрено Федеральным законом от 19 мая 1995 года № 82-ФЗ \"Об общественных объединениях\".","article_title":"Статья 123.7-1. Общественные движения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ccae61cd8a941466011470278626bda35f37252409f7e9358682ff0f90dbd28"}]$law7d0019$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
